constraints:
1 ≤ N, arr[i] ≤ 10^{5}

expected time complexity: O(N)
expected auxiliary space: O(1)

standard_solution_code:
class Solution:

	def maxXor(self, a, n):
		start = 0
		for i in range(18, -1, -1):
			ma = -1
			k = -1
			for j in range(start, n):
				if a[j] & 1 << i and (ma == -1 or ma < a[j]):
					ma = a[j]
					k = j
			if k == -1:
				continue
			(a[k], a[start]) = (a[start], a[k])
			start += 1
			for j in range(start, n):
				if a[j] & 1 << i:
					a[j] ^= ma
		ans = 0
		for j in range(n):
			if ans < ans ^ a[j]:
				ans ^= a[j]
		return ans
